class Solution {
  public int minSizeSubarray(int[] nums, int target) {
    long total = 0;
    for (int x : nums) total += x;
    long cycles = target / total, rem = target % total;
    int n = nums.length, best = Integer.MAX_VALUE;
    long sum = 0;
    int left = 0;
    for (int right = 0; right < 2 * n; right++) {
      sum += nums[right % n];
      while (sum > rem && left <= right) sum -= nums[left++ % n];
      if (sum == rem) best = Math.min(best, right - left + 1);
    }
    if (rem == 0) return (int) (cycles * n);
    return best == Integer.MAX_VALUE ? -1 : (int) (cycles * n + best);
  }
}
